UPDATE Resources SET ResourceClassType = CASE ResourceType
  WHEN 'RESOURCE_CAMELS' THEN 'RESOURCECLASS_CITY' WHEN 'RESOURCE_CLAY' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_COTTON' THEN 'RESOURCECLASS_FACTORY' WHEN 'RESOURCE_COWRIE' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_CRABS' THEN 'RESOURCECLASS_BONUS' WHEN 'RESOURCE_FISH' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_LIMESTONE' THEN 'RESOURCECLASS_EMPIRE' WHEN 'RESOURCE_HARDWOOD' THEN 'RESOURCECLASS_EMPIRE'
  WHEN 'RESOURCE_HORSES' THEN 'RESOURCECLASS_BONUS' WHEN 'RESOURCE_IRON' THEN 'RESOURCECLASS_FACTORY'
  WHEN 'RESOURCE_SALT' THEN 'RESOURCECLASS_CITY' WHEN 'RESOURCE_HIDES' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_PEARLS' THEN 'RESOURCECLASS_CITY' WHEN 'RESOURCE_RICE' THEN 'RESOURCECLASS_EMPIRE'
  WHEN 'RESOURCE_TIN' THEN 'RESOURCECLASS_FACTORY' WHEN 'RESOURCE_WHALES' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_WINE' THEN 'RESOURCECLASS_BONUS' WHEN 'RESOURCE_SILK' THEN 'RESOURCECLASS_CITY' WHEN 'RESOURCE_TURTLES' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_WILD_GAME' THEN 'RESOURCECLASS_BONUS' WHEN 'RESOURCE_WOOL' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_COAL' THEN 'RESOURCECLASS_FACTORY' WHEN 'RESOURCE_DYES' THEN 'RESOURCECLASS_EMPIRE'
  WHEN 'RESOURCE_NITER' THEN 'RESOURCECLASS_EMPIRE' WHEN 'RESOURCE_DATES' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_FURS' THEN 'RESOURCECLASS_CITY' WHEN 'RESOURCE_INCENSE' THEN 'RESOURCECLASS_CITY'
  WHEN 'RESOURCE_GYPSUM' THEN 'RESOURCECLASS_CITY' WHEN 'RESOURCE_FLAX' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_GOLD' THEN 'RESOURCECLASS_EMPIRE' WHEN 'RESOURCE_IVORY' THEN 'RESOURCECLASS_BONUS'
  WHEN 'RESOURCE_KAOLIN' THEN 'RESOURCECLASS_FACTORY' WHEN 'RESOURCE_JADE' THEN 'RESOURCECLASS_CITY'
  WHEN 'RESOURCE_LLAMAS' THEN 'RESOURCECLASS_BONUS' WHEN 'RESOURCE_MANGOS' THEN 'RESOURCECLASS_FACTORY'
  WHEN 'RESOURCE_MARBLE' THEN 'RESOURCECLASS_EMPIRE' WHEN 'RESOURCE_TOBACCO' THEN 'RESOURCECLASS_CITY'
  WHEN 'RESOURCE_TRUFFLES' THEN 'RESOURCECLASS_BONUS' WHEN 'RESOURCE_SILVER' THEN 'RESOURCECLASS_EMPIRE'
  WHEN 'RESOURCE_RUBIES' THEN 'RESOURCECLASS_EMPIRE' WHEN 'RESOURCE_COCOA' THEN 'RESOURCECLASS_FACTORY'
  WHEN 'RESOURCE_PITCH' THEN 'RESOURCECLASS_CITY' WHEN 'RESOURCE_SPICES' THEN 'RESOURCECLASS_EMPIRE'
  WHEN 'RESOURCE_TEA' THEN 'RESOURCECLASS_FACTORY' WHEN 'RESOURCE_CITRUS' THEN 'RESOURCECLASS_FACTORY'
  WHEN 'RESOURCE_COFFEE' THEN 'RESOURCECLASS_FACTORY' WHEN 'RESOURCE_QUININE' THEN 'RESOURCECLASS_FACTORY'
  WHEN 'RESOURCE_SUGAR' THEN 'RESOURCECLASS_EMPIRE' WHEN 'RESOURCE_OIL' THEN 'RESOURCECLASS_EMPIRE'
  WHEN 'RESOURCE_RUBBER' THEN 'RESOURCECLASS_EMPIRE' ELSE ResourceClassType END;

UPDATE Resources SET Tooltip = 'LOC_MPT_MAPS_MOD_' || ResourceType || '_TOOLTIP' WHERE ResourceType IN (
 'RESOURCE_CAMELS','RESOURCE_CLAY','RESOURCE_COTTON','RESOURCE_COWRIE','RESOURCE_CRABS','RESOURCE_FISH','RESOURCE_LIMESTONE','RESOURCE_HARDWOOD','RESOURCE_HORSES','RESOURCE_IRON','RESOURCE_SALT','RESOURCE_HIDES','RESOURCE_PEARLS','RESOURCE_RICE','RESOURCE_TIN','RESOURCE_WHALES','RESOURCE_WINE','RESOURCE_SILK','RESOURCE_TURTLES','RESOURCE_WILD_GAME','RESOURCE_WOOL','RESOURCE_COAL','RESOURCE_DYES','RESOURCE_NITER','RESOURCE_DATES','RESOURCE_FURS','RESOURCE_INCENSE','RESOURCE_GYPSUM','RESOURCE_FLAX','RESOURCE_GOLD','RESOURCE_IVORY','RESOURCE_KAOLIN','RESOURCE_JADE','RESOURCE_LLAMAS','RESOURCE_MANGOS','RESOURCE_MARBLE','RESOURCE_TOBACCO','RESOURCE_TRUFFLES','RESOURCE_SILVER','RESOURCE_RUBIES','RESOURCE_COCOA','RESOURCE_PITCH','RESOURCE_SPICES','RESOURCE_TEA','RESOURCE_CITRUS','RESOURCE_COFFEE','RESOURCE_QUININE','RESOURCE_SUGAR','RESOURCE_OIL','RESOURCE_RUBBER'
);
